{
  "name": "Odin Boss Timer AI",
  "description": "Upload screenshots of Odin: Valhalla Rising boss schedules to automatically calculate spawn times."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface BossSpawn {
  bossName: string;
  spawnTime: string; // Format: HH:MM
  originalText?: string;
}

export interface ProcessingState {
  isLoading: boolean;
  error: string | null;
  success: boolean;
}

export const fileToGenerativePart = async (file: File) => {
  const base64EncodedDataPromise = new Promise<string>((resolve) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const result = reader.result as string;
      // Remove the Data URL prefix (e.g., "data:image/jpeg;base64,")
      const base64String = result.split(',')[1];
      resolve(base64String);
    };
    reader.readAsDataURL(file);
  });

  return {
    inlineData: {
      data: await base64EncodedDataPromise,
      mimeType: file.type,
    },
  };
};

import { GoogleGenAI, Type } from "@google/genai";
import { BossSpawn } from "../types";
import { fileToGenerativePart } from "../utils/fileUtils";

export const analyzeScreenshots = async (
  files: File[],
  currentTime: string
): Promise<BossSpawn[]> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing. Please check your configuration.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Prepare image parts
  const imageParts = await Promise.all(
    files.map((file) => fileToGenerativePart(file))
  );

  const prompt = `
    현재 시간은 ${currentTime}입니다.

    첨부된 이미지는 '오딘: 발할라 라이징' 게임의 보스 등장 시간표 스크린샷입니다.
    이미지에서 보스 이름과 '남은 시간' 또는 '등장 예정 시간'을 찾아서 분석해주세요.

    규칙:
    1. 각 보스의 이름과 현재 시간을 기준으로 계산된 실제 등장 시간(시:분)을 구해주세요.
    2. 등장 시간이 이미 지난 경우, 내일 날짜로 계산하거나 문맥에 맞게 가장 가까운 미래의 시간으로 계산해주세요.
    3. 결과는 등장 시간 순서대로 정렬해주세요.
    4. 보스 이름이 잘리거나 불분명할 경우 최대한 추론해서 적어주세요.

    JSON 형식으로만 반환해주세요.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [...imageParts, { text: prompt }],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              bossName: {
                type: Type.STRING,
                description: "The name of the boss",
              },
              spawnTime: {
                type: Type.STRING,
                description: "Calculated spawn time in HH:MM format (24-hour)",
              },
            },
            required: ["bossName", "spawnTime"],
          },
        },
      },
    });

    const jsonText = response.text || "[]";
    const data = JSON.parse(jsonText) as BossSpawn[];

    // Validate output
    if (!Array.isArray(data)) {
        return [];
    }

    return data;
  } catch (error) {
    console.error("Gemini Analysis Failed:", error);
    throw new Error("이미지를 분석하는 도중 오류가 발생했습니다.");
  }
};

