import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult } from "../types";
import { fileToGenerativePart } from "../utils/fileUtils";

export const analyzeScreenshots = async (
  files: File[],
  currentTime: string
): Promise<AnalysisResult> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing. Please check your configuration.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Prepare image parts
  const imageParts = await Promise.all(
    files.map((file) => fileToGenerativePart(file))
  );

  const prompt = `
    제공된 현재 시간(시스템 시간)은 ${currentTime}입니다.

    하지만, 우선적으로 **스크린샷 이미지 내의 상단 상태바 등에서 찍힌 시간(Capture Time)**을 찾아주세요.

    1. **기준 시간 설정**:
       - 이미지에서 시간을 찾을 수 있다면, 그 시간을 '기준 시간'으로 사용하세요.
       - 이미지에서 시간을 찾을 수 없다면, 제공된 ${currentTime}을 '기준 시간'으로 사용하세요.
       - 만약 이미지들 간에 시간이 조금씩 다르다면, 가장 늦은 시간을 기준으로 하세요.

    2. **보스 등장 시간 계산**:
       - 설정된 '기준 시간'에 리스트의 '남은 시간'을 더하여 등장 시간(시:분)을 계산하세요.

    3. **제외 규칙 (필수)**:
       - **"혼돈의 참수자 스네르"는 목록에서 무조건 제외하세요.**
       - 남은 시간이 '1일' 이상이거나, 정확한 시간을 알 수 없는 경우 제외하세요.

    4. **이름 변경 규칙**:
       - "분노의 모네가름" -> "지감4층"
       - "나태의 드라우그" -> "지감7층"
       - "기만의 기사 다인홀로크" -> "지감10층"

    JSON 형식으로 'referenceTime'(사용된 기준 시간)과 'bosses'(계산된 목록)을 반환하세요.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [...imageParts, { text: prompt }],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            referenceTime: {
              type: Type.STRING,
              description: "The reference time used for calculation (HH:MM), either found in screenshot or provided system time.",
            },
            bosses: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  bossName: { type: Type.STRING },
                  spawnTime: { type: Type.STRING },
                },
                required: ["bossName", "spawnTime"],
              },
            },
          },
          required: ["referenceTime", "bosses"],
        },
      },
    });

    const jsonText = response.text || "{}";
    const data = JSON.parse(jsonText) as AnalysisResult;

    // Safety check in case empty JSON or missing fields
    if (!data.bosses) {
        return { referenceTime: currentTime, bosses: [] };
    }

    return data;
  } catch (error) {
    console.error("Gemini Analysis Failed:", error);
    throw new Error("이미지를 분석하는 도중 오류가 발생했습니다.");
  }
};

import React, { useState } from 'react';
import Header from './components/Header';
import ImageUploader from './components/ImageUploader';
import BossList from './components/BossList';
import { BossSpawn, ProcessingState } from './types';
import { analyzeScreenshots } from './services/geminiService';

const App: React.FC = () => {
  const [files, setFiles] = useState<File[]>([]);
  const [schedule, setSchedule] = useState<BossSpawn[]>([]);
  const [analysisTime, setAnalysisTime] = useState<string>("");

  const [status, setStatus] = useState<ProcessingState>({
    isLoading: false,
    error: null,
    success: false,
  });

  const handleFilesSelected = (selectedFiles: File[]) => {
    setFiles(selectedFiles);
    // Reset previous results when new files are added if desired, or keep them until analyze is clicked
    if (selectedFiles.length === 0) {
        setSchedule([]);
    }
  };

  const handleAnalyze = async () => {
    if (files.length === 0) return;

    setStatus({ isLoading: true, error: null, success: false });

    try {
      // Get current system time formatted as HH:mm to serve as a fallback
      const now = new Date();
      const hours = String(now.getHours()).padStart(2, '0');
      const minutes = String(now.getMinutes()).padStart(2, '0');
      const systemTime = `${hours}:${minutes}`;

      // We pass the system time, but the service will try to find the time in the screenshot first
      const result = await analyzeScreenshots(files, systemTime);

      setSchedule(result.bosses);
      setAnalysisTime(result.referenceTime); // Use the time determined by the AI
      setStatus({ isLoading: false, error: null, success: true });
    } catch (err: any) {
      setStatus({ 
        isLoading: false, 
        error: err.message || "분석 중 오류가 발생했습니다.", 
        success: false 
      });
    }
  };

  return (
    <div className="min-h-screen bg-slate-900 text-slate-200 p-4 md:p-8">
      <div className="max-w-2xl mx-auto">
        <Header />

        <main className="space-y-8">
          <section>
            <ImageUploader 
              files={files} 
              onFilesSelected={handleFilesSelected} 
              isLoading={status.isLoading}
            />

            <div className="flex justify-center mt-4">
              <button
                onClick={handleAnalyze}
                disabled={files.length === 0 || status.isLoading}
                className={`
                  px-8 py-3 rounded-full font-bold text-lg shadow-lg transition-all transform
                  ${files.length === 0 
                    ? 'bg-slate-700 text-slate-500 cursor-not-allowed' 
                    : 'bg-gradient-to-r from-amber-500 to-orange-600 text-white hover:scale-105 hover:shadow-amber-500/25 active:scale-95'
                  }
                  ${status.isLoading ? 'opacity-75 cursor-wait' : ''}
                `}
              >
                {status.isLoading ? (
                  <span className="flex items-center">
                    <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                    분석 중...
                  </span>
                ) : (
                  "시간표 분석하기"
                )}
              </button>
            </div>
          </section>

          {status.error && (
            <div className="p-4 bg-red-900/50 border border-red-700 text-red-200 rounded-lg text-center animate-pulse">
              {status.error}
            </div>
          )}

          {status.success && (
            <BossList 
              schedule={schedule} 
              currentTimeAtAnalysis={analysisTime} 
            />
          )}
        </main>
      </div>
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult } from "../types";
import { fileToGenerativePart } from "../utils/fileUtils";

export const analyzeScreenshots = async (
  files: File[],
  currentTime: string
): Promise<AnalysisResult> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing. Please check your configuration.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Prepare interleaved parts: [Image1, Text1(Time), Image2, Text2(Time)...]
  // This informs the AI of the specific capture time for each individual screenshot.
  const parts: any[] = [];

  for (let i = 0; i < files.length; i++) {
    const file = files[i];
    const imagePart = await fileToGenerativePart(file);

    // Extract time from file.lastModified (Capture/File creation time)
    const date = new Date(file.lastModified);
    const hours = String(date.getHours()).padStart(2, '0');
    const minutes = String(date.getMinutes()).padStart(2, '0');
    const fileTime = `${hours}:${minutes}`;

    parts.push(imagePart);
    parts.push({ 
      text: `[이미지 ${i + 1} 정보] 이 스크린샷 파일의 캡쳐 시간(메타데이터)은 ${fileTime}입니다. 이 이미지에 보이는 보스들의 남은 시간은 이 ${fileTime}을 기준으로 계산하여 등장 시간을 구하세요.` 
    });
  }

  const prompt = `
    첨부된 이미지들은 '오딘: 발할라 라이징' 게임의 보스 시간표 스크린샷입니다.

    [핵심 지침: 기준 시간]
    각 이미지 바로 뒤에 제공된 **파일 캡쳐 시간**을 해당 이미지의 '현재 시간'으로 간주하세요.
    보스의 '등장 시간' = (해당 이미지의 캡쳐 시간) + (이미지에 표시된 남은 시간).
    여러 이미지의 시간이 다를 수 있으므로, 각 이미지마다 제공된 시간을 정확히 적용해야 합니다.

    [필터링 및 제외 규칙]
    1. **"혼돈의 참수자 스네르"는 결과 목록에서 무조건 제외하세요.** (가장 중요)
    2. 남은 시간이 '1일' 이상 표시되어 있거나, 정확한 시간을 파악할 수 없는 경우 제외하세요.

    [이름 변경 규칙]
    - "분노의 모네가름" -> "지감4층"
    - "나태의 드라우그" -> "지감7층"
    - "기만의 기사 다인홀로크" -> "지감10층"

    [결과 형식]
    모든 이미지에서 추출된 보스 정보를 합쳐서, 등장 시간(spawnTime) 순서대로 오름차순 정렬하여 JSON으로 반환하세요.
    'referenceTime' 필드에는 단일 이미지면 그 시간을, 여러 이미지면 "파일별 캡쳐 시간"이라고 적어주세요.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [...parts, { text: prompt }],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            referenceTime: {
              type: Type.STRING,
              description: "The reference time used (e.g., '14:30' or '파일별 캡쳐 시간')",
            },
            bosses: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  bossName: { type: Type.STRING },
                  spawnTime: { type: Type.STRING },
                },
                required: ["bossName", "spawnTime"],
              },
            },
          },
          required: ["referenceTime", "bosses"],
        },
      },
    });

    const jsonText = response.text || "{}";
    const data = JSON.parse(jsonText) as AnalysisResult;

    if (!data.bosses) {
        return { referenceTime: "정보 없음", bosses: [] };
    }

    return data;
  } catch (error) {
    console.error("Gemini Analysis Failed:", error);
    throw new Error("이미지를 분석하는 도중 오류가 발생했습니다.");
  }
};

export interface BossSpawn {
  bossName: string;
  spawnTime: string; // Format: HH:MM
  originalText?: string;
  remainingTimeText?: string; // The raw text detected for remaining time (e.g. "05:00:00")
}

export interface AnalysisResult {
  bosses: BossSpawn[];
  referenceTime: string;
}

export interface ProcessingState {
  isLoading: boolean;
  error: string | null;
  success: boolean;
}

import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult } from "../types";
import { fileToGenerativePart } from "../utils/fileUtils";

export const analyzeScreenshots = async (
  files: File[],
  currentTime: string
): Promise<AnalysisResult> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing. Please check your configuration.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Prepare interleaved parts
  const parts: any[] = [];

  for (let i = 0; i < files.length; i++) {
    const file = files[i];
    const imagePart = await fileToGenerativePart(file);

    // Extract time from file.lastModified
    const date = new Date(file.lastModified);
    const hours = String(date.getHours()).padStart(2, '0');
    const minutes = String(date.getMinutes()).padStart(2, '0');
    const fileTime = `${hours}:${minutes}`;

    parts.push(imagePart);
    parts.push({ 
      text: `[이미지 ${i + 1} 메타데이터] 파일 수정 시간: ${fileTime}. (스크린샷 내에 시계가 보이지 않을 때만 이 시간을 기준 시간으로 사용하세요)` 
    });
  }

  const prompt = `
    당신은 오딘: 발할라 라이징 게임의 보스 시간표를 계산하는 정확한 계산기입니다.

    [1단계: 기준 시간(Current Time) 확정]
    각 이미지마다 다음 우선순위로 '기준 시간'을 찾으세요.
    1순위: **이미지 우측 상단 등 상태바에 있는 시계 숫자**. (가장 정확함)
    2순위: 이미지 내 시계가 없다면, 제공된 [메타데이터 파일 수정 시간]을 사용.

    [2단계: 남은 시간(Remaining Time) 판독]
    보스 목록 옆에 있는 시간 텍스트를 정확히 읽으세요.
    - **중요 포맷 규칙**: "05:00:00" 처럼 숫자가 3덩어리면 **5시간 0분 0초**를 의미합니다. (5시 아님, 5분 아님)
    - "00:30:00" -> 30분
    - "05:00" 처럼 2덩어리면 문맥을 보되, 보통 **5시간**일 확률이 높지만 분 단위인지 확인하세요.
    - "5시간 뒤", "약 5시간" 등의 텍스트도 인식하세요.

    [3단계: 등장 시간(Spawn Time) 계산]
    수식: **기준 시간 + 남은 시간 = 등장 시간**
    - 계산 실수를 하지 마세요. 24시간 형식을 준수하세요.
    - 예: 기준시간 13:00 + 남은시간 05:00:00(5시간) = 18:00 (O), 13:05 (X - 절대 안됨)
    - 예: 기준시간 09:00 + 남은시간 05:00:00(5시간) = 14:00
    - 만약 결과가 자정을 넘어가면(24:00 이상), 24를 빼고 다음 날로 계산된 시간을 적으세요 (예: 25:30 -> 01:30).

    [4단계: 필터링 및 이름 변경]
    - 제외: "혼돈의 참수자 스네르", "1일" 이상 남은 보스.
    - 이름 변경:
      - "분노의 모네가름" -> "지감4층"
      - "나태의 드라우그" -> "지감7층"
      - "기만의 기사 다인홀로크" -> "지감10층"

    JSON 형식으로 반환하세요. 'referenceTime'은 당신이 판단한 가장 신뢰할 수 있는 기준 시간(시:분)을 적으세요.
    'remainingTimeText' 필드에는 이미지에서 읽은 원본 시간 텍스트(예: "05:00:00")를 그대로 적어주세요.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [...parts, { text: prompt }],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            referenceTime: {
              type: Type.STRING,
              description: "The base time used for calculation (e.g. '13:45' found in screenshot)",
            },
            bosses: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  bossName: { type: Type.STRING },
                  remainingTimeText: { 
                    type: Type.STRING,
                    description: "The raw text read from image (e.g. '05:00:00' or '5시간')",
                  },
                  spawnTime: { 
                    type: Type.STRING, 
                    description: "Calculated time HH:MM (referenceTime + remainingTimeText)",
                  },
                },
                required: ["bossName", "spawnTime", "remainingTimeText"],
              },
            },
          },
          required: ["referenceTime", "bosses"],
        },
      },
    });

    const jsonText = response.text || "{}";
    const data = JSON.parse(jsonText) as AnalysisResult;

    if (!data.bosses) {
        return { referenceTime: "정보 없음", bosses: [] };
    }

    return data;
  } catch (error) {
    console.error("Gemini Analysis Failed:", error);
    throw new Error("이미지를 분석하는 도중 오류가 발생했습니다.");
  }
};

